def parse_json(json_str):
    def parse_value():
        nonlocal i
        if i >= len(json_str):
            raise ValueError("Unexpected end of string")

        char = json_str[i]

        if char == '{':
            return parse_object()
        elif char == '[':
            return parse_array()
        elif char == '"':
            return parse_string()
        elif char.isdigit() or char in ('-', '.'):
            return parse_number()
        elif char == 't':
            return parse_true()
        elif char == 'f':
            return parse_false()
        elif char == 'n':
            return parse_null()
        else:
            raise ValueError("Invalid character in JSON string")

    def parse_object():
        nonlocal i
        if json_str[i] != '{':
            raise ValueError("Expected '{' at the beginning of an object")
        i += 1

        obj = {}
        while i < len(json_str) and json_str[i] != '}':
            key = parse_string()
            if i >= len(json_str) or json_str[i] != ':':
                raise ValueError("Expected ':' after key in object")
            i += 1
            value = parse_value()
            obj[key] = value
            if i < len(json_str) and json_str[i] == ',':
                i += 1
        if i >= len(json_str) or json_str[i] != '}':
            raise ValueError("Expected '}' at the end of an object")
        i += 1
        return obj

    def parse_array():
        nonlocal i
        if json_str[i] != '[':
            raise ValueError("Expected '[' at the beginning of an array")
        i += 1

        arr = []
        while i < len(json_str) and json_str[i] != ']':
            value = parse_value()
            arr.append(value)
            if i < len(json_str) and json_str[i] == ',':
                i += 1
        if i >= len(json_str) or json_str[i] != ']':
            raise ValueError("Expected ']' at the end of an array")
        i += 1
        return arr

    def parse_string():
        nonlocal i
        if json_str[i] != '"':
            raise ValueError("Expected '\"' at the beginning of a string")
        i += 1

        result = []
        while i < len(json_str) and json_str[i] != '"':
            if json_str[i] == '\\':
                i += 1
                if i >= len(json_str):
                    raise ValueError("Unexpected end of string")
                char = json_str[i]
                if char == 'n':
                    result.append('\n')
                elif char == 'r':
                    result.append('\r')
                elif char == 't':
                    result.append('\t')
                elif char == '\\':
                    result.append('\\')
                elif char == '"':
                    result.append('"')
                else:
                    raise ValueError("Invalid escape sequence in string")
            else:
                result.append(json_str[i])
            i += 1
        if i >= len(json_str) or json_str[i] != '"':
            raise ValueError("Unexpected end of string")
        i += 1
        return ''.join(result)

    def parse_number():
        nonlocal i
        if json_str[i] == '-':
            i += 1
        if i >= len(json_str) or not json_str[i].isdigit():
            raise ValueError("Invalid number format")
        while i < len(json_str) and json_str[i].isdigit():
            i += 1
        if i < len(json_str) and json_str[i] == '.':
            i += 1
            if i >= len(json_str) or not json_str[i].isdigit():
                raise ValueError("Invalid number format")
            while i < len(json_str) and json_str[i].isdigit():
                i += 1
        if i < len(json_str) and (json_str[i] == 'e' or json_str[i] == 'E'):
            i += 1
            if i >= len(json_str) or (json_str[i] == '+' or json_str[i] == '-'):
                i += 1
            if i >= len(json_str) or not json_str[i].isdigit():
                raise ValueError("Invalid number format")
            while i < len(json_str) and json_str[i].isdigit():
                i += 1
        return float(json_str[i - len(json_str):i])

    def parse_true():
        nonlocal i
        if json_str[i:i+4] != 'true':
            raise ValueError("Invalid 'true' token")
        i += 4
        return True

    def parse_false():
        nonlocal i
        if json_str[i:i+5] != 'false':
            raise ValueError("Invalid 'false' token")
        i += 5
        return False

    def parse_null():
        nonlocal i
        if json_str[i:i+4] != 'null':
            raise ValueError("Invalid 'null' token")
        i += 4
        return None

    i = 0
    return parse_value()

