def parse_json(json_str):
    def parse_value(s):
        if s[0] == '{':
            return parse_object(s)
        elif s[0] == '[':
            return parse_array(s)
        elif s[0].isdigit() or s[0] in ('-', '.'):
            return parse_number(s)
        elif s[0] == '"':
            return parse_string(s)
        elif s[0] in ('t', 'f'):
            return parse_boolean(s)
        elif s[0] == 'n':
            return parse_null(s)
        else:
            raise ValueError("Invalid JSON")

    def parse_object(s):
        if s[0] != '{':
            raise ValueError("Invalid JSON")
        s = s[1:]  # Remove the opening brace
        result = {}
        while s and s[0] != '}':
            key = parse_string(s)
            if s[0] != ':':
                raise ValueError("Invalid JSON")
            s = s[1:]  # Remove the colon
            value = parse_value(s)
            result[key] = value
            if s and s[0] == ',':
                s = s[1:]  # Remove the comma
        if s and s[0] != '}':
            raise ValueError("Invalid JSON")
        s = s[1:]  # Remove the closing brace
        return result

    def parse_array(s):
        if s[0] != '[':
            raise ValueError("Invalid JSON")
        s = s[1:]  # Remove the opening bracket
        result = []
        while s and s[0] != ']':
            value = parse_value(s)
            result.append(value)
            if s and s[0] == ',':
                s = s[1:]  # Remove the comma
        if s and s[0] != ']':
            raise ValueError("Invalid JSON")
        s = s[1:]  # Remove the closing bracket
        return result

    def parse_number(s):
        start = 0
        if s[0] == '-':
            start = 1
        if s[start] == '0':
            if len(s) > 1 and s[1] in ('x', 'X'):
                return int(s[start:start+2], 16)
            return 0
        while start < len(s) and s[start].isdigit():
            start += 1
        if start < len(s) and s[start] == '.':
            start += 1
            while start < len(s) and s[start].isdigit():
                start += 1
        if start < len(s) and (s[start] == 'e' or s[start] == 'E'):
            start += 1
            if start < len(s) and (s[start] == '+' or s[start] == '-'):
                start += 1
            while start < len(s) and s[start].isdigit():
                start += 1
        return float(s[:start])

    def parse_string(s):
        if s[0] != '"':
            raise ValueError("Invalid JSON")
        s = s[1:]  # Remove the opening quote
        start = 0
        while start < len(s) and s[start] != '"':
            if s[start] == '\\':
                start += 1
                if start == len(s):
                    raise ValueError("Invalid JSON")
                if s[start] in ('"', '\\', '/', 'b', 'f', 'n', 'r', 't'):
                    start += 1
                else:
                    if start + 1 < len(s) and s[start:start+2] in ('u', 'U'):
                        start += 2
                        for _ in range(4):
                            if start + 1 < len(s) and s[start:start+2].isxdigit():
                                start += 2
                            else:
                                raise ValueError("Invalid JSON")
            else:
                start += 1
        s = s[start + 1:]  # Remove the closing quote
        return s[:start]

    def parse_boolean(s):
        if s.startswith('true'):
            return True
        elif s.startswith('false'):
            return False
        else:
            raise ValueError("Invalid JSON")

    def parse_null(s):
        if s.startswith('null'):
            return None
        else:
            raise ValueError("Invalid JSON")

    # Check for trailing commas
    if json_str.endswith(',}'):
        json_str = json_str[:-2]
    elif json_str.endswith(',]'):
        json_str = json_str[:-2]

    return parse_value(json_str)

