def parse_json(json_str):
    if not json_str:
        raise ValueError("Unexpected end of JSON string")

    def parse_value():
        nonlocal i
        if i >= len(json_str):
            raise ValueError("Unexpected end of JSON string")

        char = json_str[i]

        if char == '"':
            return parse_string()
        elif char == '[':
            return parse_array()
        elif char == '{':
            return parse_object()
        elif char.isdigit() or char in ('-', '.'):
            return parse_number()
        elif char in ('t', 'f'):
            return parse_boolean()
        elif char == 'n':
            return parse_null()
        else:
            raise ValueError("Invalid JSON character: " + char)

    def parse_string():
        nonlocal i
        i += 1
        result = []
        while i < len(json_str) and json_str[i] != '"':
            if json_str[i] == '\\':
                i += 1
                if i >= len(json_str):
                    raise ValueError("Unexpected end of JSON string")
                char = json_str[i]
                if char == '"':
                    result.append('"')
                elif char == '\\':
                    result.append('\\')
                elif char == '/':
                    result.append('/')
                elif char == 'b':
                    result.append('\b')
                elif char == 'f':
                    result.append('\f')
                elif char == 'n':
                    result.append('\n')
                elif char == 'r':
                    result.append('\r')
                elif char == 't':
                    result.append('\t')
                else:
                    raise ValueError("Invalid escape sequence: " + char)
