        elif tokens[0].isdigit() or (tokens[0] == '-' and tokens[1].isdigit()):
            tokens.pop(0)
            result = 0
            while tokens and (tokens[0].isdigit() or tokens[0] == '.'):
                if tokens[0] == '.':
                    tokens.pop(0)
